sys_script_include.script:
var serviceDiscoveryKPI = Class.create();
serviceDiscoveryKPI.prototype = {
    initialize: function() {
        // Weights for the different discovery metrics
        this.discoveryMetrics = {
            success_rate: 0.3,
            coverage: 0.3,
            freshness: 0.2,
            consistency: 0.2
        };
    },
    calculate: function() {
        var discoveredGR = new GlideRecord('cmdb_ci_service_discovered');
        discoveredGR.query();
        var metrics = {
            overall_effectiveness: 0,
            services: [],
            patterns: this._analyzePatternEffectiveness(),
            recommendations: []
        };
        var count = 0;
        while (discoveredGR.next()) {
            var serviceMetrics = this._analyzeDiscoveredService(discoveredGR);
            metrics.services.push(serviceMetrics);
            metrics.overall_effectiveness += serviceMetrics.effectiveness_score;
            count++;
        }
        metrics.overall_effectiveness = (count > 0) ? (metrics.overall_effectiveness / count) : 0;
        metrics.recommendations = this._generateRecommendations(metrics);
        return metrics;
    },
    _analyzeDiscoveredService: function(discoveredService) {
        return {
            name: discoveredService.getValue('name'),
            effectiveness_score: this._calculateEffectivenessScore(discoveredService),
            last_discovery: discoveredService.getValue('last_discovered'),
            status: discoveredService.getValue('status'),
            coverage: this._calculateCoverage(discoveredService),
            consistency: this._checkConsistency(discoveredService)
        };
    },
    _calculateEffectivenessScore: function(discoveredService) {
        // Determine success score: 100 if successful, else 0
        var status = discoveredService.getValue('last_discovery_status');
        var successScore = (status == "Success") ? 100 : 0;

        var coverageScore = this._calculateCoverage(discoveredService);
        var freshnessScore = this._calculateFreshness(discoveredService);
        var consistencyScore = this._checkConsistency(discoveredService);

        // Combine scores using the defined weights
        var overall = (successScore * this.discoveryMetrics.success_rate) +
                      (coverageScore * this.discoveryMetrics.coverage) +
                      (freshnessScore * this.discoveryMetrics.freshness) +
                      (consistencyScore * this.discoveryMetrics.consistency);
        return overall;
    },
    _calculateCoverage: function(discoveredService) {
        // If a coverage value exists, use it; otherwise, assume full coverage (100)
        var coverage = discoveredService.getValue('discovery_coverage');
        if (!coverage) {
            return 100;
        }
        return parseFloat(coverage);
    },
    _calculateFreshness: function(discoveredService) {
        // Calculate freshness based on the time since the last discovery.
        // More recent discovery yields a higher score.
        var lastDiscovered = discoveredService.getValue('last_discovered');
        if (!lastDiscovered) {
            return 0;
        }
        var lastDiscoveryDate = new GlideDateTime(lastDiscovered);
        var now = new GlideDateTime();
        // Compute the duration between now and the last discovered time.
        var duration = GlideDateTime.subtract(now, lastDiscoveryDate);
        var diffSeconds = duration.getNumericValue(); // Duration in seconds
        var diffHours = diffSeconds / 3600;

        // Define a simple scoring scheme:
        // Within 24 hours: 100, within 48 hours: 80, within 72 hours: 60, else: 40
        if (diffHours <= 24) {
            return 100;
        } else if (diffHours <= 48) {
            return 80;
        } else if (diffHours <= 72) {
            return 60;
        } else {
            return 40;
        }
    },
    _checkConsistency: function(discoveredService) {
        // For consistency, if the last discovery status is "Success", assume high consistency.
        // Otherwise, assume lower consistency.
        var status = discoveredService.getValue('last_discovery_status');
        if (status == "Success") {
            return 100;
        } else {
            return 90;
        }
    },
    _analyzePatternEffectiveness: function() {
        // Analyze overall discovery patterns across services.
        // This example computes the overall success and failure percentages.
        var gr = new GlideRecord('cmdb_ci_service_discovered');
        gr.query();
        var total = 0;
        var successes = 0;
        while (gr.next()) {
            total++;
            if (gr.getValue('last_discovery_status') == "Success") {
                successes++;
            }
        }
        var successRate = (total > 0) ? (successes / total) * 100 : 0;
        return {
            total_services: total,
            success_rate_percentage: successRate,
            failure_rate_percentage: 100 - successRate
        };
    },
    _generateRecommendations: function(metrics) {
        var recommendations = [];
        // Simple recommendation logic:
        // If overall effectiveness is below 70, suggest improvements; otherwise, note good performance.
        if (metrics.overall_effectiveness < 70) {
            recommendations.push("Improve discovery success rate and freshness.");
        } else {
            recommendations.push("Discovery process is performing well.");
        }
        return recommendations;
    }
};
